/* Test the production mixer, including its callback, without opening a device.
   Expected routing, impulse responses, ring boundaries and quantization are
   checked independently; DSP vectors are generated by unmodified Ryujinx. */
#include "../../runtime/audio_mixer.c"
#include <assert.h>
#include <unistd.h>
_Noreturn void runtime_fail(const char *s){fprintf(stderr,"probe failure: %s\n",s);exit(2);}
void *ipc_guest(uint64_t at,uint64_t n){(void)n;if(!at)runtime_fail("null probe memory");return (void *)(uintptr_t)at;}
void dm_guest_write_prepare(void *p,size_t n){(void)p;(void)n;}
int audio_buffer_empty(const AudrenWaveBuffer *b){return !b->address||!b->size||b->end<=b->start;}
const void *ipc_arg(const IpcRequest *r,uint32_t a,uint32_t n){(void)r;(void)a;(void)n;runtime_fail("unexpected IPC argument");}
void ipc_out(IpcResponse *r,const void *p,uint32_t n){(void)r;(void)p;(void)n;runtime_fail("unexpected IPC output");}
_Noreturn void ipc_unimplemented(const IpcSession *s,const IpcRequest *r){(void)s;(void)r;runtime_fail("unexpected IPC");}
uint32_t runtime_event_new(void){return 1;}
uint32_t runtime_event_readable(uint32_t h){return h;}
static unsigned long checks;
static void check(int ok,const char *s){if(!ok)runtime_fail(s);checks++;}
static void near(float x,float y,const char *s){check(isfinite(x)&&fabsf(x-y)<=2e-5f+fabsf(y)*2e-5f,s);}
static AudioRenderer renderer(int frames){
    AudioRenderer r={.param={.sample_rate=48000,.sample_count=frames,.mix_buffer_count=12,.voice_count=1,.sink_count=1,.effect_count=1},.revision=0x3b564552u};
    r.voices=calloc(1,sizeof *r.voices);r.channels=calloc(6,sizeof *r.channels);r.effects=calloc(1,sizeof *r.effects);r.mixes=calloc(1,sizeof *r.mixes);r.sinks=calloc(1,sizeof *r.sinks);
    r.mixes[0]=(AudrenMixIn){.volume=1,.buffer_count=12,.in_use=1,.dest_mix_id=-1,.dest_splitter_id=~0u};audio_mixer_open(&r);return r;
}
static void destroy(AudioRenderer *r){audio_mixer_close(r);free(r->voices);free(r->channels);free(r->effects);free(r->mixes);free(r->sinks);}
static void read_exact(FILE *f,void *p,size_t n){if(fread(p,1,n,f)!=n)runtime_fail("short reference");}
static int read_int(FILE *f){int n;read_exact(f,&n,4);return n;}
static void vectors(const char *path){
    FILE *f=fopen(path,"rb");if(!f)runtime_fail("reference missing");check(read_int(f)==0x41454658,"reference magic");int cases=read_int(f);
    for(int t=0;t<cases;t++){
        int type=read_int(f),revision=read_int(f),channels=read_int(f),frames=read_int(f),blocks=read_int(f);AudioRenderer r=renderer(frames);Mixer *m=r.mixer;
        r.revision=((uint32_t)('0'+revision)<<24)|0x564552u;
        for(int b=0;b<blocks;b++){
            r.effects[0].type=(uint8_t)type;r.effects[0].enabled=(uint8_t)read_int(f);r.effects[0].is_new=(uint8_t)read_int(f);r.effects[0].mix_id=0;
            read_exact(f,r.effects[0].specific,160);audio_mixer_update_effects(&r);memset(m->buf,0,(size_t)m->nbuf*frames*4);
            for(int c=0;c<channels;c++)read_exact(f,m->buf+c*frames,(size_t)frames*4);
            mix_effects(&r,0);
            for(int c=0;c<channels;c++)for(int k=0;k<frames;k++){float want;read_exact(f,&want,4);float actual=m->buf[(6+c)*frames+k];
                if(!isfinite(actual)||fabsf(actual-want)>2e-5f+fabsf(want)*2e-5f){fprintf(stderr,"graph type%d rev%d channels%d block%d c%d k%d got%.9g want%.9g\n",type,revision,channels,b,c,k,actual,want);exit(1);}checks++;}
            if(type==9){float want[8],actual[8]={0};read_exact(f,want,sizeof want);audio_mixer_effect_result(&r,0,actual,sizeof actual);for(int k=0;k<8;k++)near(actual[k],want[k],"graph compressor statistics");}
        }
        destroy(&r);
    }
    check(fgetc(f)==EOF,"reference EOF");fclose(f);
}
static void simple_effects(void){
    AudioRenderer r=renderer(16);Mixer *m=r.mixer;AudrenBufferMixParam p={.count=2};p.input[0]=0;p.output[0]=2;p.volume[0]=.5f;p.input[1]=1;p.output[1]=2;p.volume[1]=-.25f;
    r.effects[0]=(AudrenEffectIn){.type=1,.enabled=1};memcpy(r.effects[0].specific,&p,sizeof p);
    for(int k=0;k<16;k++){m->buf[k]=(k-8)/128.f;m->buf[16+k]=(8-k)/128.f;}audio_mixer_update_effects(&r);mix_effects(&r,0);
    for(int k=0;k<16;k++)near(m->buf[32+k],(k-8)*.75f/128,"buffer mix accumulation");
    AudrenBiquadEffectV1 b={.channels=1,.numerator={8192,4096,0},.denominator={4096,0}};b.output[0]=1;r.effects[0]=(AudrenEffectIn){.type=6,.enabled=1,.is_new=1};memcpy(r.effects[0].specific,&b,sizeof b);
    memset(m->buf,0,12*16*4);m->buf[0]=1;audio_mixer_update_effects(&r);mix_effects(&r,0);near(m->buf[16],.5f,"biquad impulse0");near(m->buf[17],.375f,"biquad impulse1");
    float tail=m->buf[31]*.25f;r.effects[0].is_new=0;b.status=2;memcpy(r.effects[0].specific,&b,sizeof b);memset(m->buf,0,12*16*4);audio_mixer_update_effects(&r);mix_effects(&r,0);near(m->buf[16],tail,"biquad continuity");
    r.effects[0].enabled=0;m->buf[0]=.75f;audio_mixer_update_effects(&r);mix_effects(&r,0);near(m->buf[16],.75f,"biquad bypass");
    AudrenBiquadEffectV2 bf={.channels=1,.numerator={.5f,.25f,0},.denominator={.25f,0}};bf.output[0]=1;r.revision=0x3f564552u;r.effects[0]=(AudrenEffectIn){.type=6,.enabled=1,.is_new=1};memcpy(r.effects[0].specific,&bf,sizeof bf);
    memset(m->buf,0,12*16*4);m->buf[0]=1;audio_mixer_update_effects(&r);mix_effects(&r,0);near(m->buf[16],.5f,"float biquad impulse0");near(m->buf[17],.375f,"float biquad impulse1");
    uint8_t pcm24[]={0,0,0x80,0xff,0xff,0x7f,0,0,0,0,0,0x40};ServerVoice voice={.in={.sample_format=FMT_PCM24,.channel_count=2}};
    voice.buffers[0]=(AudrenWaveBuffer){.address=(uintptr_t)pcm24,.size=sizeof pcm24,.end=2};Walk walk={.v=&voice,.valid={1},.abuf=-1};
    near(sample_at(&walk,0),-1,"PCM24 signed minimum");near(sample_at(&walk,1),8388607.f/8388608,"PCM24 signed maximum");walk.offset=1;near(sample_at(&walk,0),0,"PCM24 silence");near(sample_at(&walk,1),.5f,"PCM24 interleaving");voice.buffers[0].size=5;walk.offset=0;near(sample_at(&walk,1),0,"PCM24 truncated sample");
    uint8_t encoded[8]={0x0f,0x77};int16_t coefficients[16]={32767,32767};AudrenWaveBuffer ab={.address=(uintptr_t)encoded,.size=8};Walk edge={.h1=32767,.h2=32767};
    check(adpcm_next(&edge,&ab,coefficients,0)==32767,"ADPCM positive accumulator saturation");encoded[1]=0x88;edge.h1=edge.h2=-32768;check(adpcm_next(&edge,&ab,coefficients,0)==-32768,"ADPCM negative accumulator saturation");
    uint32_t capture[64]={0};capture[0]=0x12345678;capture[18]=7;AudrenAuxParam a={.channels=2,.capacity=32,.send_info=(uintptr_t)capture};a.input[0]=0;a.input[1]=1;
    r.effects[0]=(AudrenEffectIn){.type=8,.enabled=1,.is_new=1};memcpy(r.effects[0].specific,&a,sizeof a);for(int k=0;k<16;k++){m->buf[k]=(k-8)/32768.f;m->buf[16+k]=(8-k)/32768.f;}audio_mixer_update_effects(&r);mix_effects(&r,0);
    for(int k=0;k<16;k++){check((int32_t)capture[32+k]==k-8,"capture left");check((int32_t)capture[48+k]==8-k,"capture right");}
    check(capture[0]==0x12345678 && capture[18]==7,"capture preserves CPU header/loss count");check(capture[19]==32,"capture count advances independently of wrapped cursor");
    capture[3]=100;capture[19]=132;capture[2]=3;capture[18]=7;mix_effects(&r,0);check(capture[19]==164&&capture[18]==39,"capture producer counters retain CPU baseline");
    capture[3]=50;capture[19]=49;capture[2]=10;capture[18]=9;mix_effects(&r,0);check(capture[19]==49&&capture[18]==9,"capture counter-difference saturation");
    capture[3]=UINT32_MAX-5;capture[19]=UINT32_MAX-1;capture[18]=7;mix_effects(&r,0);check(capture[19]==30&&capture[18]==7,"capture counter uint32 wrap without false loss");
    r.effects[0].enabled=0;capture[16]=3;capture[17]=4;capture[19]=5;mix_effects(&r,0);check(!capture[16]&&!capture[17]&&!capture[19]&&capture[18]==7,"capture bypass cursor reset");
    uint8_t ring[20];memset(ring,0xaa,sizeof ring);CircularSinkParam cs={.address=(uintptr_t)ring,.size=20,.channels=2,.format=FMT_PCM16};cs.input[1]=1;
    r.sinks[0]=(AudrenSinkIn){.type=SINK_CIRCULAR,.in_use=1};memcpy(r.sinks[0].name,&cs,sizeof cs);mix_circular_sink(&r,0);
    for(int k=0;k<32;k++){int16_t value;memcpy(&value,ring+(k*2)%20,2);int last=k;while(last+10<32)last+=10;int want=last<16?last-8:8-(last-16);check(value==want,"circular sink sample/wrap");}
    check(audio_mixer_sink_written(&r,0)==0,"circular initial written position");mix_circular_sink(&r,0);mix_circular_sink(&r,0);check(audio_mixer_sink_written(&r,0)==4,"circular delayed written position");
    destroy(&r);
}
static void reverb_early_modes(void){
    for(int mode=0;mode<5;mode++){
        AudioRenderer r=renderer(240);Mixer *m=r.mixer;
        AudrenReverbParam p={.channels=1,.channel_max=6,.sample_rate=48*16384,.early_mode=mode,.early_gain=16384,.late_mode=0,.decay=1000*16384,.hf_decay=13107,.reverb_gain=16384,.out_gain=16384};p.output[0]=6;
        r.effects[0]=(AudrenEffectIn){.type=4,.enabled=1,.is_new=1};memcpy(r.effects[0].specific,&p,sizeof p);audio_mixer_update_effects(&r);
        float response[3120];for(int b=0;b<13;b++){memset(m->buf,0,12*240*sizeof(float));if(!b)m->buf[0]=1;mix_effects(&r,0);memcpy(response+b*240,m->buf+6*240,240*sizeof(float));}
        /* Selected impulses from the five Ryujinx.Audio early-reflection tables,
           indexed by mode (the C# reference reads only the first). No late/dry signal. */
        if(mode==0){near(response[1],.70f,"Room first reflection");near(response[169],.68f,"Room 3.5ms reflection");}
        if(mode==1){near(response[169],0,"Chamber must not use Room timing");near(response[567],.68f,"Chamber 11.8ms reflection");}
        if(mode==2)near(response[1],1.f,"Hall coincident .5+.5 reflections");
        if(mode==3){near(response[716],.94f,"Cathedral 14.9ms reflection");near(response[1590],.93f,"Cathedral 33.1ms reflection");}
        if(mode==4)for(int k=0;k<3120;k++)near(response[k],0,"Disabled early reflections remain silent");
        destroy(&r);
    }
}
static void ring_output(void){
    Mixer *m=calloc(1,sizeof *m);m->frame=240;m->unit_ok=1;atomic_store(&m->playing,1);float samples[480],out[1024];for(int k=0;k<480;k++)samples[k]=.25f;
    AudioBufferList io={.mNumberBuffers=1,.mBuffers={{.mNumberChannels=2,.mDataByteSize=sizeof out,.mData=out}}};
    output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);check(atomic_load(&m->rd)==0&&!atomic_load(&m->underruns),"startup prefill is not underrun");for(int k=0;k<1024;k++)near(out[k],0,"prefill silence");
    for(int n=0;n<7;n++)output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);for(int k=0;k<1024;k++)near(out[k],.25f,"prefill resumes real samples");
    for(int n=0;n<3;n++)pull(m,NULL,NULL,0,512,&io);check(atomic_load(&m->underruns)==1&&atomic_load(&m->missing_frames)==128,"real underrun recorded");for(int k=768;k<1024;k++)near(out[k],0,"underrun padding");
    output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);check(atomic_load(&m->underruns)==1,"rebuffer does not inflate underruns");
    for(int n=0;n<7;n++)output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);near(out[0],.25f,"rebuffer recovery");atomic_store(&m->playing,0);pull(m,NULL,NULL,0,512,&io);check(atomic_load(&m->rd)==atomic_load(&m->wr)&&atomic_load(&m->underruns)==1,"stop flush without underrun");
    /* runtime_audio_hold: while the first frame waits for the warm-up, the output is silent and what the game writes is dropped */
    atomic_store(&m->playing,1);m->ready=0;runtime_audio_hold(1);for(int n=0;n<8;n++)output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);
    for(int k=0;k<1024;k++)near(out[k],0,"hold silence");check(atomic_load(&m->rd)==atomic_load(&m->wr),"hold drops the backlog");
    runtime_audio_hold(0);for(int n=0;n<8;n++)output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);near(out[0],.25f,"sound after the hold");
    AudioRenderer r={.mixer=m};audio_mixer_set_running(&r,1);for(int n=0;n<8;n++)output_push(m,samples,240);audio_mixer_set_running(&r,0);audio_mixer_set_running(&r,1);
    for(int k=0;k<480;k++)samples[k]=.5f;for(int n=0;n<8;n++)output_push(m,samples,240);pull(m,NULL,NULL,0,512,&io);near(out[0],.5f,"rapid stop/start drops stale queued audio");check(atomic_load(&m->underruns)==1,"resume keeps underrun accounting");
    atomic_store(&m->rd,0);atomic_store(&m->wr,RING_FRAMES);uint64_t before=atomic_load(&m->wr);output_push(m,samples,240);check(atomic_load(&m->wr)==before&&atomic_load(&m->overruns)==1,"full ring drops atomically");free(m);
    m=calloc(1,sizeof *m);m->frame=240;m->unit_ok=1;atomic_store(&m->playing,1);
    for(int n=0;n<16 && !m->ready;n++){output_push(m,samples,240);pull(m,NULL,NULL,0,240,&io);}
    check(m->ready,"playback starts after bounded prefill");
    /* The producer is descheduled right after playback starts: the prefill, less the block the first pull took, must come
       out intact (default 20 ms: three more 5-ms pulls, a 15-ms gap), and the next pull is a real underrun. */
    int intact=prefill_blocks()-1;check(intact>=1,"prefill leaves headroom after the first pull");
    for(int n=0;n<intact;n++){pull(m,NULL,NULL,0,240,&io);for(int k=0;k<480;k++)near(out[k],.5f,"producer scheduling gap within the prefill");}
    check(!atomic_load(&m->underruns),"scheduling headroom avoids dropout");
    pull(m,NULL,NULL,0,240,&io);check(atomic_load(&m->underruns)==1,"a gap longer than the prefill underruns");free(m);
    /* A Bluetooth route change or CoreAudio callback stall lets the 5-ms producer fill the 341-ms ring while pull() is
       paused; when pull() resumes on a live device, stale backlog past the headroom cap is skipped back to prefill. */
    m=calloc(1,sizeof *m);m->frame=240;m->unit_ok=1;atomic_store(&m->playing,1);
    for(int k=0;k<480;k++)samples[k]=.25f;for(int n=0;n<20;n++)output_push(m,samples,240);
    for(int k=0;k<480;k++)samples[k]=.75f;for(int n=0;n<4;n++)output_push(m,samples,240);
    pull(m,NULL,NULL,0,240,&io);near(out[0],.75f,"device stall backlog trims stale audio back to prefill");
    check(atomic_load(&m->wr)-atomic_load(&m->rd)==720,"trimmed backlog leaves remaining prefill headroom");free(m);
    /* TOTK_AUDIO_PREFILL_MS: milliseconds rounded up to 5-ms blocks; unset is the default 20; anything else is refused. */
    check(prefill_blocks_for(NULL)==4&&prefill_blocks_for("")==4,"prefill default 20 ms");
    check(prefill_blocks_for("0")==0&&prefill_blocks_for("20")==4&&prefill_blocks_for("40")==8&&prefill_blocks_for("22")==5,"prefill milliseconds to blocks");
    check(prefill_blocks_for("-1")<0&&prefill_blocks_for("abc")<0&&prefill_blocks_for("20ms")<0&&prefill_blocks_for("600")<0,"prefill rejects bad values");
}
static void diagnostic_capture(void){
    char path[]="/tmp/totk-audio-capture-XXXXXX";int fd=mkstemp(path);check(fd>=0,"capture fixture");close(fd);unlink(path);setenv("TOTK_AUDIO_CAPTURE",path,1);unsetenv("TOTK_AUDIO_CAPTURE_DELAY_S");
    AudioRenderer r=renderer(16);Mixer *m=r.mixer;check(m->capture_worker,"capture worker started");m->capture_limit=32;m->capture_skip=8;
    float samples[32]={0};capture_copy(m,samples,16);check(!m->capture_frames&&!m->capture_started,"capture waits for audio");
    for(int k=0;k<32;k++)samples[k]=(k+1)/128.f;
    capture_copy(m,samples,16);check(m->capture_frames==8&&!m->capture_done,"capture delay");capture_copy(m,samples,16);capture_copy(m,samples,16);check(m->capture_frames==32&&m->capture_done,"capture completes exactly");destroy(&r);
    FILE *f=fopen(path,"rb");check(f!=NULL,"capture output");float got[64];read_exact(f,got,sizeof got);check(fgetc(f)==EOF,"capture length");fclose(f);
    for(int k=0;k<64;k++){int source=k<16?k+16:k<48?k-16:k-48;near(got[k],samples[source],"capture worker samples");}
    r=renderer(16);check(!((Mixer *)r.mixer)->capture_worker,"existing capture never overwritten");destroy(&r);unlink(path);unsetenv("TOTK_AUDIO_CAPTURE");
}
int main(int argc,char **argv){setenv("TOTK_AUDIO_OFF","1",1);check(atomic_load(&g_audio_hold)==1,"silent until the warm-up");runtime_audio_hold(0);unsetenv("TOTK_AUDIO_CAPTURE");if(argc!=2)return 2;vectors(argv[1]);simple_effects();reverb_early_modes();ring_output();diagnostic_capture();printf("{\"status\":\"pass\",\"checks\":%lu,\"scope\":\"production effect graph, routing, capture/circular buffers, output prefill/recovery/stop, async recording\"}\n",checks);return 0;}
